# owner: platform
import unittest

from hourglass.parsing import parse_span
from hourglass.gaps import find_gaps
from hourglass.errors import OutsideHoursError

# ---
def spans(*texts):
    return [parse_span(text) for text in texts]

class FindGapsTests(unittest.TestCase):
    hours = parse_span("09:00-17:00")

    def test_gap_in_the_middle(self):
        result = find_gaps(
            spans("09:00-12:00", "13:00-17:00"), self.hours
        )
        self.assertEqual(
            result, ["gap 12:00-13:00 (60 min)"]
        )

    def test_gaps_at_both_edges(self):
        result = find_gaps(spans("10:00-16:00"), self.hours)
        self.assertEqual(result, [
            "gap 09:00-10:00 (60 min)",
            "gap 16:00-17:00 (60 min)"
        ])

    def test_full_coverage_has_no_gaps(self):
        result = find_gaps(
            spans("09:00-13:00", "12:00-17:00"), self.hours
        )
        self.assertEqual(result, [])

    def test_touching_spans_leave_no_gap(self):
        result = find_gaps(
            spans("09:00-13:00", "13:00-17:00"), self.hours
        )
        self.assertEqual(result, [])

    def test_unsorted_input(self):
        result = find_gaps(
            spans("14:00-17:00", "09:00-12:00"), self.hours
        )
        self.assertEqual(
            result, ["gap 12:00-14:00 (120 min)"]
        )

    def test_nobody_working_is_one_big_gap(self):
        result = find_gaps([], self.hours)
        self.assertEqual(
            result, ["gap 09:00-17:00 (480 min)"]
        )

    def test_span_starting_early_raises(self):
        with self.assertRaises(OutsideHoursError):
            find_gaps(spans("08:00-12:00"), self.hours)

    def test_span_ending_late_raises(self):
        with self.assertRaises(OutsideHoursError):
            find_gaps(spans("12:00-17:30"), self.hours)

if __name__ == "__main__":
    unittest.main()
